/**
 * Test Suite for Receipt Split Feature
 *
 * Specifications covered:
 * - #{#spl1a} Split receipt into partial amounts
 * - #{#spl1b} Split group tracking
 * - #{#spl2b} Split amount validation
 * - #{#spl4a} Category independence
 * - #{#spl4b} Transaction matching independence
 * - #{#spl5a} Data integrity (atomic operations)
 * - #{#spl5b} Storage access (shared image)
 * - #{#spl6a} Deletion behavior
 * - #{#spl7a} Per-split date override
 * - #{#spl7c} Split date validation
 *
 * Authority: platform (spl1a, spl1b), system (spl5a, spl5b), developer (rest)
 * Priority: High/Critical
 *
 * TDD Phase: RED - All tests should FAIL until splitReceipt() is implemented
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ReceiptService } from './ReceiptService';
import type { ReceiptRow } from '$lib/models/Receipt';
import { makeReceiptRow } from '$lib/tests/builders/rowBuilders';

// Mock Supabase client
vi.mock('$lib/supabaseClient', () => ({
	supabase: {
		auth: {
			getUser: vi.fn()
		},
		from: vi.fn(),
		storage: {
			from: vi.fn()
		}
	}
}));

vi.mock('$lib/utils/dateValidation', () => ({
	isSuspiciousDate: vi.fn().mockReturnValue(false)
}));

vi.mock('$lib/utils/signedUrl', () => ({
	getSignedReceiptUrl: vi.fn()
}));

import { supabase } from '$lib/supabaseClient';
import { isSuspiciousDate } from '$lib/utils/dateValidation';

/**
 * Helper: create a mock ReceiptRow for testing (split-scenario defaults on top of
 * the shared builder)
 */
function makeReceipt(overrides: Partial<ReceiptRow> = {}): ReceiptRow {
	return makeReceiptRow({
		id: 'receipt-original',
		user_id: 'test-user-id',
		receipt_image_path: 'test-user-id/abc123.jpg',
		transaction_date: '2026-02-15',
		total_amount: 120.0,
		tax: 12.0,
		merchant_name: 'Amazon',
		credit_card_name: 'Visa',
		credit_card_last_4: '4242',
		currency: 'CAD',
		matched_transaction_id: 'txn-original',
		created_at: '2026-02-15T10:00:00Z',
		suspicious_date: false,
		...overrides
	});
}

/** Typed replacement for `supabase.auth.getUser` mock results (module-mocked vi.fn). */
type GetUserResult = Awaited<ReturnType<typeof supabase.auth.getUser>>;
function mockAuthUser(user: { id: string } | null) {
	vi.mocked(supabase.auth.getUser).mockResolvedValue({
		data: { user },
		error: null
	} as unknown as GetUserResult);
}

describe('ReceiptService - Receipt Split', () => {
	let service: ReceiptService;
	let mockInsert: ReturnType<typeof vi.fn>;
	let mockUpdate: ReturnType<typeof vi.fn>;
	let mockSelect: ReturnType<typeof vi.fn>;
	let mockEq: ReturnType<typeof vi.fn>;
	let mockSingle: ReturnType<typeof vi.fn>;
	let mockDelete: ReturnType<typeof vi.fn>;

	beforeEach(() => {
		vi.clearAllMocks();
		service = new ReceiptService(supabase);

		// Setup auth mock
		mockAuthUser({ id: 'test-user-id' });

		// Setup Supabase mock chain
		// The chain needs to support:
		//   from('receipts').select('*').eq('id', x).single()  -- fetch
		//   from('receipts').insert({}).select('*').single()    -- insert
		//   from('receipts').update({}).eq('id', x).select('*').single() -- update
		//   from('receipts').delete().eq('id', x)              -- delete (rollback)
		mockSingle = vi.fn();
		mockSelect = vi
			.fn()
			.mockReturnValue({ single: mockSingle, eq: vi.fn().mockReturnValue({ single: mockSingle }) });
		mockEq = vi.fn().mockReturnValue({ select: mockSelect, single: mockSingle });
		mockInsert = vi.fn().mockReturnValue({ select: mockSelect });
		mockUpdate = vi.fn().mockReturnValue({ eq: mockEq });
		mockDelete = vi.fn().mockReturnValue({ eq: vi.fn().mockResolvedValue({ error: null }) });

		(supabase as { from: typeof supabase.from }).from = vi.fn().mockReturnValue({
			insert: mockInsert,
			update: mockUpdate,
			select: mockSelect,
			delete: mockDelete,
			eq: mockEq
		}) as unknown as typeof supabase.from;

