/**
 * Narrow hand-written Supabase `Database` schema for integration tests.
 *
 * The repo has no generated Supabase types (`supabase gen types`), and an
 * untyped `createClient()` collapses every table to `never`, so `.insert(...)`
 * payloads and row property access fail type-checking. This schema types only
 * the tables and columns the tests actually touch — extend it as tests grow,
 * or replace it wholesale if generated types are ever added.
 *
 * Row types reuse the app's model interfaces where they exist. `AsRecord`
 * re-maps interfaces into anonymous object types because interfaces lack the
 * implicit index signature that postgrest-js's `GenericTable` constraint
 * (`Record<string, unknown>`) requires.
 */

import type { ReceiptRow } from '$lib/models/Receipt';
import type { TransactionRow, TransactionInsert, TransactionUpdate } from '$lib/models/Transaction';

type AsRecord<T> = { [K in keyof T]: T[K] };

export type FamilyRow = {
	id: string;
	name: string;
	created_at: string;
};

export type FamilyMemberRow = {
	family_id: string;
	user_id: string;
	status: string;
	role: string;
	is_default: boolean;
	created_at: string;
};

export type CategoryRow = {
	id: string;
	family_id: string;
	name: string;
	color: string | null;
	created_at: string;
	updated_at: string;
};

export type VendorCategoryRuleRow = {
	id: string;
	family_id: string;
	vendor_pattern: string;
	category_id: string;
	created_at: string;
};

export type TestDatabase = {
	public: {
		Tables: {
			families: {
				Row: FamilyRow;
				Insert: { id?: string; name: string };
				Update: Partial<FamilyRow>;
				Relationships: [];
			};
			family_members: {
				Row: FamilyMemberRow;
				Insert: {
					family_id: string;
					user_id: string;
					status: string;
					role: string;
					is_default?: boolean;
				};
				Update: Partial<FamilyMemberRow>;
				Relationships: [];
			};
			categories: {
				Row: CategoryRow;
				Insert: { id?: string; family_id: string; name: string; color?: string | null };
				Update: Partial<CategoryRow>;
				Relationships: [];
			};
			receipts: {
				Row: AsRecord<ReceiptRow>;
				Insert: Partial<AsRecord<ReceiptRow>>;
				Update: Partial<AsRecord<ReceiptRow>>;
				Relationships: [];
			};
			transactions: {
				Row: AsRecord<TransactionRow>;
				Insert: AsRecord<TransactionInsert>;
				Update: AsRecord<TransactionUpdate>;
				Relationships: [];
			};
			vendor_category_rules: {
				Row: VendorCategoryRuleRow;
				Insert: { id?: string; family_id: string; vendor_pattern: string; category_id: string };
				Update: Partial<VendorCategoryRuleRow>;
				Relationships: [];
			};
		};
		Views: Record<string, never>;
		Functions: Record<string, never>;
		Enums: Record<string, never>;
		CompositeTypes: Record<string, never>;
	};
};

