7	/** Chainable Supabase query stub. Tests set `data`/`error` and assert on the vi.fn() calls. */
8	interface MockQueryBuilder {
9		data: unknown;
10		error: { message: string; code?: string } | null;
11		select: Mock;
12		eq: Mock;
13		insert: Mock;
14		update: Mock;
15		delete: Mock;
