27	/**
28	 * CategoryService Test Suite
29	 *
30	 * Tests for #{#exp3a} - Family Category Management
31	 *
32	 * Specification: specs/specifications/expense-categorization.md
33	 * Authority: developer
34	 * Priority: High
35	 *
36	 * Requirements:
37	 * 1. Categories must be scoped to families (family_id foreign key)
38	 * 2. New families must receive a default set of common categories on creation
39	 * 3. Default categories must include the full list defined in CategoryService
40	 * 4. Family members must be able to create custom categories
41	 * 5. Family members must be able to rename existing categories (affects all expenses in category)
42	 * 6. Family members must be able to delete categories (with confirmation if expenses exist in category)
43	 * 7. Category names must be unique per family (case-insensitive)
44	 * 8. Categories must support optional color coding for visual distinction
45	 */
46	
47	// Mock Supabase client
48	const createMockSupabaseClient = (): SupabaseClient => {
49		const mockQuery = {
50			data: null,
51			error: null,
52			select: vi.fn().mockReturnThis(),
53			eq: vi.fn().mockReturnThis(),
54			insert: vi.fn().mockReturnThis(),
55			update: vi.fn().mockReturnThis(),
56			delete: vi.fn().mockReturnThis(),
57			single: vi.fn(function (this: MockQueryBuilder) {
58				// When single() is called, return data directly (not in array)
59				if (Array.isArray(this.data) && this.data.length > 0) {
60					return Promise.resolve({ data: this.data[0], error: this.error });
61				}
62				return Promise.resolve({ data: this.data, error: this.error });
