import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { CategoryService } from './CategoryService';

type Mock = ReturnType<typeof vi.fn>;

/** Chainable Supabase query stub. Tests set `data`/`error` and assert on the vi.fn() calls. */
interface MockQueryBuilder {
	data: unknown;
	error: { message: string; code?: string } | null;
	select: Mock;
	eq: Mock;
	insert: Mock;
	update: Mock;
	delete: Mock;
	single: Mock;
	order: Mock;
	returns: Mock;
	then: Mock;
}

/** Retrieve the query stub behind `client.from(table)` with its mock surface exposed. */
function getMockQuery(client: SupabaseClient, table: string): MockQueryBuilder {
	return client.from(table) as unknown as MockQueryBuilder;
}

/**
 * CategoryService Test Suite
 *
 * Tests for #{#exp3a} - Family Category Management
 *
 * Specification: specs/specifications/expense-categorization.md
 * Authority: developer
 * Priority: High
 *
 * Requirements:
 * 1. Categories must be scoped to families (family_id foreign key)
 * 2. New families must receive a default set of common categories on creation
 * 3. Default categories must include the full list defined in CategoryService
 * 4. Family members must be able to create custom categories
 * 5. Family members must be able to rename existing categories (affects all expenses in category)
 * 6. Family members must be able to delete categories (with confirmation if expenses exist in category)
 * 7. Category names must be unique per family (case-insensitive)
 * 8. Categories must support optional color coding for visual distinction
 */

// Mock Supabase client
const createMockSupabaseClient = (): SupabaseClient => {
	const mockQuery = {
		data: null,
		error: null,
		select: vi.fn().mockReturnThis(),
		eq: vi.fn().mockReturnThis(),
		insert: vi.fn().mockReturnThis(),
		update: vi.fn().mockReturnThis(),
		delete: vi.fn().mockReturnThis(),
		single: vi.fn(function (this: MockQueryBuilder) {
			// When single() is called, return data directly (not in array)
			if (Array.isArray(this.data) && this.data.length > 0) {
				return Promise.resolve({ data: this.data[0], error: this.error });
			}
			return Promise.resolve({ data: this.data, error: this.error });
		}),
		order: vi.fn().mockReturnThis(),
		returns: vi.fn().mockReturnThis(),
		then: vi.fn(function (this: MockQueryBuilder, resolve) {
			// Make the query object thenable for async/await
			return resolve({ data: this.data, error: this.error });
		})
	};

	return {
		from: vi.fn().mockReturnValue(mockQuery),
		rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
		auth: {
			getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user-id' } } } })
		}
	} as unknown as SupabaseClient;
};

