}

/**
 * Get existing vendor rule for a merchant
 *
 * @param familyId - Family ID
 * @param merchantName - Merchant name to look up
 * @returns Vendor rule with category info, or null if not found
 *
 * Specification: #{#exp5a} - Vendor Rule Management (Family-scoped)
 */
async getVendorRule(
	familyId: string,
	merchantName: string
): Promise<{ category_id: string; category_name: string } | null> {
	if (!familyId || !merchantName) {
		return null;
	}

	const vendorPattern = this.normalizeVendor(merchantName);

	const { data, error } = await this.supabase
		.from('vendor_category_rules')
		.select('category_id, categories(name)')
		.eq('family_id', familyId)
		.eq('vendor_pattern', vendorPattern)
		.single();

	if (error || !data) {
		return null;
	}

	const categories = coerceEmbed<{ name: string } | null>(data.categories);

	return {
		category_id: data.category_id,
		category_name: categories?.name || 'Unknown'
	};
}

