import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { ExchangeRateService } from './ExchangeRateService';

/**
 * Test suite for ExchangeRateService
 *
 * Specifications covered:
 * - #{#fcr2a} Exchange Rate Fetching via Bank of Canada API
 *
 * Fetches daily exchange rates from the Bank of Canada Valet API
 * for a specific currency and date. Called at receipt save time.
 */

describe('ExchangeRateService #{#fcr2a}', () => {
	let originalFetch: typeof globalThis.fetch;

	beforeEach(() => {
		originalFetch = globalThis.fetch;
	});

	afterEach(() => {
		globalThis.fetch = originalFetch;
	});

	describe('fetchRate', () => {
		it('should fetch EUR rate for a specific date', async () => {
			globalThis.fetch = vi.fn().mockResolvedValue({
				ok: true,
				json: () =>
					Promise.resolve({
						observations: [
							{
								d: '2026-03-11',
								FXEURCAD: { v: '1.6058' }
							}
						]
					})
			});

			const rate = await ExchangeRateService.fetchRate('EUR', '2026-03-11');

			expect(rate).toBe(1.6058);
			expect(globalThis.fetch).toHaveBeenCalledWith(expect.stringContaining('FXEURCAD'));
			expect(globalThis.fetch).toHaveBeenCalledWith(expect.stringContaining('start_date='));
		});

		it('should fetch USD rate', async () => {
			globalThis.fetch = vi.fn().mockResolvedValue({
				ok: true,
				json: () =>
					Promise.resolve({
						observations: [
							{
								d: '2026-03-11',
								FXUSDCAD: { v: '1.3918' }
							}
						]
					})
			});

			const rate = await ExchangeRateService.fetchRate('USD', '2026-03-11');

			expect(rate).toBe(1.3918);
		});

		it('should fetch GBP rate', async () => {
			globalThis.fetch = vi.fn().mockResolvedValue({
				ok: true,
				json: () =>
					Promise.resolve({
						observations: [
							{
								d: '2026-03-11',
								FXGBPCAD: { v: '1.8407' }
							}
						]
					})
			});

			const rate = await ExchangeRateService.fetchRate('GBP', '2026-03-11');

			expect(rate).toBe(1.8407);
		});

		it('should return most recent rate when exact date has no data (weekend)', async () => {
			// Saturday March 14 has no rate, but the range fetch returns Friday March 13
			globalThis.fetch = vi.fn().mockResolvedValue({
				ok: true,
				json: () =>
					Promise.resolve({
						observations: [
							{
								d: '2026-03-12',
								FXEURCAD: { v: '1.5900' }
							},
							{
								d: '2026-03-13',
								FXEURCAD: { v: '1.6010' }
							}
						]
