=== $lib/types/Category ===
/**
 * Category Types
 *
 * Used in #{#exp2a} - Category Assignment UI
 * and throughout the expense categorization system
 *
 * Single source of truth for the Category shape — CategoryService re-exports
 * this type rather than redefining it. `color` is nullable to match the
 * database column; display sites apply the shared fallback colour.
 *
 * Updated to use family_id instead of user_id for family-shared categories
 */

export interface Category {
	id: string;
	name: string;
	color: string | null;
	family_id?: string;
	created_at?: string;
	updated_at?: string;
}

/** Fallback swatch colour for categories without a stored colour (gray-500). */
export const DEFAULT_CATEGORY_COLOR = '#6B7280';

export interface CategoryWithCounts extends Category {
	expense_count?: number;
	total_amount?: number;
}

