import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import type { Category } from '$lib/types/Category';
import { makeCategory } from '$lib/tests/builders/rowBuilders';
import { supabaseMock, resetHarness } from '$lib/tests/harness/appMocks';

/**
 * Behaviour tests for the real <CategoryDropdown> (#{#exp2a}, #{#exp3b}).
 *
 * The previous spec was hollow: it re-declared the component's filter / validate /
 * keyboard-navigation logic as ~25 local helpers and asserted against those copies,
 * so it could pass even if CategoryDropdown.svelte was completely broken. These
 * render the actual component and exercise it through its public props and the DOM
 * — display, search, keyboard selection, click-to-select, click-outside, and the
 * inline "create category" validation branches.
 *
 * The component imports the Supabase singleton and ExpenseService at module scope
 * (both only used for vendor-rule loading, which is gated on merchantName+familyId).
 * We mock those boundaries so a bare render stays pure; no test here passes a
 * merchant, so ExpenseService is never actually invoked.
 */
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
vi.mock('$lib/services/ExpenseService', () => ({ ExpenseService: class {} }));

import CategoryDropdown from './CategoryDropdown.svelte';

const categories: Category[] = [
	{ id: 'cat-1', name: 'Groceries', color: '#10B981' },
	{ id: 'cat-2', name: 'Dining', color: '#F59E0B' },
	{ id: 'cat-3', name: 'Transportation', color: '#3B82F6' },
	{ id: 'cat-4', name: 'Entertainment', color: '#8B5CF6' }
];

/** Open the dropdown by clicking the trigger; returns the render result. */
async function openDropdown(props: Record<string, unknown> = {}) {
	const screen = render(CategoryDropdown, { categories, ...props });
	await screen.getByTestId('category-trigger').click();
	await expect.element(screen.getByTestId('category-dropdown')).toBeVisible();
	return screen;
}

describe('CategoryDropdown', () => {
	beforeEach(resetHarness);

	it('shows "Uncategorized" when no category is assigned', async () => {
		const screen = render(CategoryDropdown, { categories });
		await expect.element(screen.getByTestId('category-display')).toHaveTextContent('Uncategorized');
	});

	it('shows the current category name when one is assigned', async () => {
		const screen = render(CategoryDropdown, { categories, currentCategory: categories[0] });
		await expect.element(screen.getByTestId('category-display')).toHaveTextContent('Groceries');
	});

	it('opens the dropdown with a search box and every category when the trigger is clicked', async () => {
		const screen = await openDropdown();

		await expect.element(screen.getByTestId('category-search')).toBeVisible();
		await expect.element(screen.getByTestId('category-option-cat-1')).toBeVisible();
		await expect.element(screen.getByTestId('category-option-cat-4')).toBeVisible();
	});

	it('filters options by a case-insensitive substring match', async () => {
		const screen = await openDropdown();

		await screen.getByTestId('category-search').fill('GRO');

		await expect.element(screen.getByTestId('category-option-cat-1')).toBeVisible();
		await expect.element(screen.getByTestId('category-option-cat-2')).not.toBeInTheDocument();
	});

	it('shows "No categories found" when the search matches nothing', async () => {
		const screen = await openDropdown();

		await screen.getByTestId('category-search').fill('zzz');

		await expect.element(screen.getByText('No categories found')).toBeVisible();
	});

	it('calls onCategorySelect and closes the menu when an option is clicked', async () => {
		const onCategorySelect = vi.fn();
		const screen = await openDropdown({ onCategorySelect });

		await screen.getByTestId('category-option-cat-3').click();

		expect(onCategorySelect).toHaveBeenCalledOnce();
		expect(onCategorySelect.mock.calls[0][0]).toMatchObject({
			id: 'cat-3',
			name: 'Transportation'
		});
		await expect.element(screen.getByTestId('category-dropdown')).not.toBeInTheDocument();
	});

	it('selects the highlighted option via ArrowDown + Enter (keyboard navigation)', async () => {
		const onCategorySelect = vi.fn();
		const screen = await openDropdown({ onCategorySelect });
		const search = screen.getByTestId('category-search').element();

		// Default highlight is the first option; one ArrowDown moves it to the second.
		search.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true }));
		await expect
			.element(screen.getByTestId('category-option-cat-2'))
			.toHaveAttribute('aria-selected', 'true');

		search.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));

		expect(onCategorySelect).toHaveBeenCalledOnce();
		expect(onCategorySelect.mock.calls[0][0]).toMatchObject({ id: 'cat-2', name: 'Dining' });
	});

	it('closes the menu when Escape is pressed', async () => {
		const screen = await openDropdown();
		const search = screen.getByTestId('category-search').element();

		search.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));

		await expect.element(screen.getByTestId('category-dropdown')).not.toBeInTheDocument();
	});

	it('closes the menu when a click lands outside it', async () => {
		const screen = await openDropdown();

		document.body.click();

		await expect.element(screen.getByTestId('category-dropdown')).not.toBeInTheDocument();
	});

	describe('inline category creation (#{#exp3b})', () => {
		it('reveals the creation form when "Create new category..." is clicked', async () => {
			const screen = await openDropdown();

			await screen.getByTestId('create-category-option').click();

			await expect.element(screen.getByTestId('inline-creation-form')).toBeVisible();
			await expect.element(screen.getByTestId('new-category-name-input')).toBeVisible();
		});

		it('rejects an empty name with "Category name required" and does not dispatch', async () => {
			const onCreateNewCategory = vi.fn();
			const screen = await openDropdown({ onCreateNewCategory });

			await screen.getByTestId('create-category-option').click();
			await screen.getByTestId('create-category-button').click();

			await expect
				.element(screen.getByTestId('creation-error'))
				.toHaveTextContent('Category name required');
			expect(onCreateNewCategory).not.toHaveBeenCalled();
		});

		it('rejects a duplicate name (case-insensitive) with "Category already exists"', async () => {
			const onCreateNewCategory = vi.fn();
			const screen = await openDropdown({ onCreateNewCategory });

			await screen.getByTestId('create-category-option').click();
			await screen.getByTestId('new-category-name-input').fill('groceries');
			await screen.getByTestId('create-category-button').click();

			await expect
				.element(screen.getByTestId('creation-error'))
				.toHaveTextContent('Category already exists');
			expect(onCreateNewCategory).not.toHaveBeenCalled();
		});

		it('dispatches onCreateNewCategory with the trimmed name for a valid unique name', async () => {
			const onCreateNewCategory = vi.fn();
			const screen = await openDropdown({ onCreateNewCategory });

			await screen.getByTestId('create-category-option').click();
			await screen.getByTestId('new-category-name-input').fill('  Travel  ');
			await screen.getByTestId('create-category-button').click();

			expect(onCreateNewCategory).toHaveBeenCalledOnce();
			expect(onCreateNewCategory.mock.calls[0][0]).toMatchObject({ name: 'Travel' });
		});
	});
});

