import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import type { Category } from '$lib/types/Category';
import { makeReceiptRow } from '$lib/tests/builders/rowBuilders';
import { supabaseMock } from '$lib/tests/harness/appMocks';

// Signed URLs and the Supabase singleton must not hit the network when the modal
// (and its CategoryDropdown / image viewer children) mount.
vi.mock('$lib/utils/signedUrl', () => ({
	getSignedReceiptUrl: async (path: string) => `https://mock/${path}`
}));
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));

import ReceiptEditModal from './ReceiptEditModal.svelte';

/**
 * Behavior tests for ReceiptEditModal (#{#rct3a}, #{#rct5a}, #{#rct7b}, #{#dtv2d},
 * #{#rmc1a}, #{#ofn4a}).
 *
 * Replaces ReceiptEditModal.spec.ts, which was mostly (a) reimplemented component
 * logic asserted against its own copy (validation, dirty-checking, category
 * selection), (b) tautologies (`expect(typeof true).toBe('boolean')`), and (c)
 * regex over the component source. This renders the real component and drives it:
 * validation gating, save emission, the unsaved-changes guard, the suspicious-date
 * notice, the category control, and the original-filename row.
 */
const CATEGORIES: Category[] = [
	{ id: 'cat-1', name: 'Groceries', color: '#10B981' } as Category,
	{ id: 'cat-2', name: 'Dining', color: '#F59E0B' } as Category
];

describe('ReceiptEditModal', () => {
	beforeEach(() => vi.restoreAllMocks());

	describe('save validation (#{#rct3a}, #{#rct5a})', () => {
		it('blocks save and shows an error when merchant, amount and date are all empty', async () => {
			const onsave = vi.fn();
			const receipt = makeReceiptRow({
				merchant_name: null,
				total_amount: null,
				transaction_date: null
			});

			const screen = render(ReceiptEditModal, { receipt, show: true, onsave });

			await screen.getByRole('button', { name: 'Save Changes' }).click();

			await expect
				.element(screen.getByText('Receipt must have at least a merchant name, amount, or date'))
				.toBeVisible();
			expect(onsave).not.toHaveBeenCalled();
		});

		it('emits save with the edited receipt when it has at least one field', async () => {
			const onsave = vi.fn();
			const receipt = makeReceiptRow({ merchant_name: 'Test Merchant', currency: 'CAD' });

			const screen = render(ReceiptEditModal, { receipt, show: true, onsave });

			await screen.getByRole('button', { name: 'Save Changes' }).click();

			await vi.waitFor(() => expect(onsave).toHaveBeenCalledTimes(1));
			expect(onsave.mock.calls[0][0]).toMatchObject({ merchant_name: 'Test Merchant' });
		});
	});

	describe('unsaved-changes guard (#{#rct7b})', () => {
		it('warns before closing when a field has been edited', async () => {
			const onclose = vi.fn();
			const receipt = makeReceiptRow({ merchant_name: 'Original' });

			const screen = render(ReceiptEditModal, { receipt, show: true, onclose });

			await screen.getByRole('textbox', { name: 'Merchant Name (optional)' }).fill('Changed');
			await screen.getByRole('button', { name: 'Close modal' }).click();

			await expect.element(screen.getByText('Discard changes?')).toBeVisible();
			await expect.element(screen.getByRole('button', { name: 'Keep Editing' })).toBeVisible();
			expect(onclose).not.toHaveBeenCalled();
		});

		it('closes immediately when nothing has been edited', async () => {
			const onclose = vi.fn();
			const receipt = makeReceiptRow({ merchant_name: 'Original' });

			const screen = render(ReceiptEditModal, { receipt, show: true, onclose });

			await screen.getByRole('button', { name: 'Close modal' }).click();

			await vi.waitFor(() => expect(onclose).toHaveBeenCalledTimes(1));
			await expect.element(screen.getByText('Discard changes?')).not.toBeInTheDocument();
		});
	});

	describe('suspicious-date notice (#{#dtv2d})', () => {
		it('shows the notice when the receipt date is flagged suspicious', async () => {
			const receipt = makeReceiptRow({ suspicious_date: true });
			const screen = render(ReceiptEditModal, { receipt, show: true });

			await expect.element(screen.getByText('This date looks unusual')).toBeVisible();
		});

		it('hides the notice when the date is not flagged', async () => {
			const receipt = makeReceiptRow({ suspicious_date: false });
			const screen = render(ReceiptEditModal, { receipt, show: true });

			await expect.element(screen.getByText('This date looks unusual')).not.toBeInTheDocument();
		});
	});

	describe('category control (#{#rmc1a})', () => {
		it('renders the category control when categories are provided', async () => {
			const receipt = makeReceiptRow();
			const screen = render(ReceiptEditModal, { receipt, show: true, categories: CATEGORIES });

			await expect.element(screen.getByRole('button', { name: 'Category' })).toBeVisible();
		});

		it('omits the category control when no categories are provided', async () => {
			const receipt = makeReceiptRow();
			const screen = render(ReceiptEditModal, { receipt, show: true });

			await expect
				.element(screen.getByRole('button', { name: 'Category' }))
				.not.toBeInTheDocument();
		});
	});

	describe('original filename (#{#ofn4a})', () => {
		it('shows the original filename row when set', async () => {
			const receipt = makeReceiptRow({ original_filename: 'Costco 2026-03-12.pdf' });
			const screen = render(ReceiptEditModal, { receipt, show: true });

			await expect.element(screen.getByText(/Costco 2026-03-12\.pdf/)).toBeVisible();
		});

		it('omits the row when there is no original filename', async () => {
			const receipt = makeReceiptRow({ original_filename: null });
			const screen = render(ReceiptEditModal, { receipt, show: true });

			await expect.element(screen.getByText(/Original file:/)).not.toBeInTheDocument();
		});
	});
});

