import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import type { Category } from '$lib/types/Category';
import { makeExpense } from './builders/rowBuilders';
import {
	pageStore,
	supabaseMock,
	ExpenseServiceStub,
	CategoryServiceStub,
	ReceiptServiceStub,
	setExpenses,
	setCategories,
	setSession,
	fakeSession,
	resetHarness
} from './harness/appMocks';

// Replace every module boundary the expenses page touches on mount. Unlike the
// receipts page, this one needs a non-null family id or it renders a "No family"
// error instead of loading expenses. See harness/appMocks.ts.
vi.mock('$app/stores', () => ({ page: pageStore }));
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
vi.mock('$app/navigation', () => ({ goto: () => {}, replaceState: () => {} }));
vi.mock('$app/paths', () => ({ resolve: (p: string) => p }));
vi.mock('$lib/utils/signedUrl', () => ({
	getSignedReceiptUrls: async () => ({}),
	getSignedReceiptUrl: async () => null
}));
vi.mock('$lib/utils/familyUtils', () => ({ getDefaultFamilyId: async () => 'family-1' }));
vi.mock('$lib/services/ExpenseService', () => ({ ExpenseService: ExpenseServiceStub }));
vi.mock('$lib/services/CategoryService', () => ({ CategoryService: CategoryServiceStub }));
vi.mock('$lib/services/ReceiptService', () => ({ ReceiptService: ReceiptServiceStub }));

import ExpensesPage from '../../routes/expenses/+page.svelte';

/**
 * Behavior tests for the expenses page (#{#exp1a}, #{#exp9a}).
 *
 * Replaces the source-introspection expenses-page.spec.ts, which regex'd the page
 * and layout source. The layout-side claims (Expenses tab, active state,
 * preserveFilters) are covered by layout-render.svelte.spec.ts; these render the
 * real page and assert its empty state, table columns, formatted row, and count.
 * Built on the route-render harness (harness/appMocks.ts).
 */
describe('expenses page', () => {
	beforeEach(resetHarness);

	it('shows the "No expenses found" empty state when there are none', async () => {
		setSession(fakeSession());
		setExpenses([]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByRole('heading', { name: 'No expenses found' })).toBeVisible();
	});

	it('renders the sortable columns and the Receipt/Category cell controls', async () => {
		setSession(fakeSession());
		setExpenses([makeExpense()]);

		const screen = render(ExpensesPage);

		// #{#exp9a} criterion 1/6: Date, Merchant, Amount are the sortable columns
		// (DataTable gives those role=columnheader).
		for (const col of ['Date', 'Merchant', 'Amount']) {
			await expect.element(screen.getByRole('columnheader', { name: col })).toBeVisible();
		}
		// Receipt column renders the thumbnail (criterion 5) and Category column renders
		// the assignment control for an uncategorized expense (criterion 4).
		await expect.element(screen.getByAltText(/^Receipt for/)).toBeVisible();
		await expect.element(screen.getByRole('button', { name: 'Category' })).toBeVisible();
	});

	it('renders a row with the merchant and currency-formatted amount', async () => {
		setSession(fakeSession());
		setExpenses([
			makeExpense({ merchant_name: 'Paris Café', total_amount: 42.5, currency: 'CAD' })
		]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('Paris Café')).toBeVisible();
		// #{#exp9a} criterion 3: amount formatted with symbol + 2 decimals.
		await expect.element(screen.getByText('$42.50')).toBeVisible();
	});

	it('renders a foreign-currency expense with its estimated CAD amount (#{#fcr4a})', async () => {
		// The amountCell computes the estimate inline as total_amount * exchange_rate_to_cad
		// (45 * 1.53 = 68.85) and passes it to formatCurrencyWithEstimate. This guards that
		// inline page math, which no unit test otherwise covers.
		setSession(fakeSession());
		setExpenses([makeExpense({ total_amount: 45, currency: 'EUR', exchange_rate_to_cad: 1.53 })]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('€45.00 (≈$68.85)')).toBeVisible();
	});

	it('renders a foreign-currency expense without an estimate when the rate is null', async () => {
		setSession(fakeSession());
		setExpenses([makeExpense({ total_amount: 45, currency: 'EUR', exchange_rate_to_cad: null })]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('€45.00')).toBeVisible();
		await expect.element(screen.getByText(/≈\$/)).not.toBeInTheDocument();
	});

	it('shows the expense count summary', async () => {
		setSession(fakeSession());
		setExpenses([makeExpense(), makeExpense({ receipt_id: 'receipt-2' })]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText(/Showing 2 of 2 expenses/)).toBeVisible();
	});

	it('filters to only uncategorized expenses when the Uncategorized button is toggled (#{#exp6a})', async () => {
		setSession(fakeSession());
		setCategories([{ id: 'cat-1', name: 'Food', color: '#10B981' } as Category]);
		setExpenses([
			makeExpense({
				receipt_id: 'a',
				merchant_name: 'Alpha Store',
				category_id: 'cat-1',
				category_name: 'Food'
			}),
			makeExpense({ receipt_id: 'b', merchant_name: 'Beta Store', category_id: null })
		]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('Alpha Store')).toBeVisible();
		await expect.element(screen.getByText('Beta Store')).toBeVisible();

		// The filter toggle is the first "Uncategorized" button (FilterPanel renders above
		// the table, so it precedes the row's own category-cell trigger / dropdown option).
		await screen
			.getByRole('button', { name: /Uncategorized/ })
			.first()
			.click();

		await expect.element(screen.getByText('Beta Store')).toBeVisible();
		await expect.element(screen.getByText('Alpha Store')).not.toBeInTheDocument();
		// #{#flt1a} the count summary reflects the active filter.
		await expect.element(screen.getByText(/Showing 1 of 2 expenses/)).toBeVisible();
	});

	it('filters to a chosen category via the Category dropdown (#{#exp7a})', async () => {
		setSession(fakeSession());
		setCategories([
			{ id: 'cat-food', name: 'Food', color: '#10B981' } as Category,
			{ id: 'cat-travel', name: 'Travel', color: '#3B82F6' } as Category
		]);
		setExpenses([
			makeExpense({
				receipt_id: 'a',
				merchant_name: 'Grocer',
				category_id: 'cat-food',
				category_name: 'Food'
			}),
			makeExpense({
				receipt_id: 'b',
				merchant_name: 'Airline',
				category_id: 'cat-travel',
				category_name: 'Travel'
			})
		]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('Grocer')).toBeVisible();
		await expect.element(screen.getByText('Airline')).toBeVisible();

		// Open the Category filter dropdown (top of page), then pick Travel. The row's own
		// category cell also renders a 'Travel' button, so target the first (the filter).
		await screen.getByRole('button', { name: /^Category/ }).click();
		await screen.getByRole('button', { name: 'Travel' }).first().click();

		await expect.element(screen.getByText('Airline')).toBeVisible();
		await expect.element(screen.getByText('Grocer')).not.toBeInTheDocument();
	});
});

