		await expect.element(screen.getByText('€45.00 (≈$68.85)')).toBeVisible();
	});

	it('renders a foreign-currency expense without an estimate when the rate is null', async () => {
		setSession(fakeSession());
		setExpenses([makeExpense({ total_amount: 45, currency: 'EUR', exchange_rate_to_cad: null })]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('€45.00')).toBeVisible();
		await expect.element(screen.getByText(/≈\$/)).not.toBeInTheDocument();
	});

	it('shows the expense count summary', async () => {
		setSession(fakeSession());
		setExpenses([makeExpense(), makeExpense({ receipt_id: 'receipt-2' })]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText(/Showing 2 of 2 expenses/)).toBeVisible();
	});

	it('filters to only uncategorized expenses when the Uncategorized button is toggled (#{#exp6a})', async () => {
		setSession(fakeSession());
		setCategories([makeCategory({ id: 'cat-1', name: 'Food', color: '#10B981' })]);
		setExpenses([
			makeExpense({
				receipt_id: 'a',
				merchant_name: 'Alpha Store',
				category_id: 'cat-1',
				category_name: 'Food'
			}),
			makeExpense({ receipt_id: 'b', merchant_name: 'Beta Store', category_id: null })
		]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('Alpha Store')).toBeVisible();
		await expect.element(screen.getByText('Beta Store')).toBeVisible();

		// The filter toggle is the first "Uncategorized" button (FilterPanel renders above
		// the table, so it precedes the row's own category-cell trigger / dropdown option).
		await screen
			.getByRole('button', { name: /Uncategorized/ })
			.first()
			.click();

		await expect.element(screen.getByText('Beta Store')).toBeVisible();
		await expect.element(screen.getByText('Alpha Store')).not.toBeInTheDocument();
		// #{#flt1a} the count summary reflects the active filter.
		await expect.element(screen.getByText(/Showing 1 of 2 expenses/)).toBeVisible();
	});

	it('filters to a chosen category via the Category dropdown (#{#exp7a})', async () => {
		setSession(fakeSession());
		setCategories([
			{ id: 'cat-food', name: 'Food', color: '#10B981' } as Category,
			{ id: 'cat-travel', name: 'Travel', color: '#3B82F6' } as Category
		]);
		setExpenses([
			makeExpense({
				receipt_id: 'a',
				merchant_name: 'Grocer',
				category_id: 'cat-food',
				category_name: 'Food'
			}),
			makeExpense({
				receipt_id: 'b',
				merchant_name: 'Airline',
				category_id: 'cat-travel',
				category_name: 'Travel'
			})
		]);

		const screen = render(ExpensesPage);

		await expect.element(screen.getByText('Grocer')).toBeVisible();
		await expect.element(screen.getByText('Airline')).toBeVisible();

		// Open the Category filter dropdown (top of page), then pick Travel. The row's own
		// category cell also renders a 'Travel' button, so target the first (the filter).
		await screen.getByRole('button', { name: /^Category/ }).click();
		await screen.getByRole('button', { name: 'Travel' }).first().click();

		await expect.element(screen.getByText('Airline')).toBeVisible();
		await expect.element(screen.getByText('Grocer')).not.toBeInTheDocument();
	});
});

