import { readFileSync, writeFileSync } from 'fs';
import { execSync } from 'child_process';

// Files carrying dead #{#..} tags OR stale TDD/ceremony headers.
const list = execSync(
	"grep -rlE '#\\{#|TDD Phase|should FAIL until|Specifications covered|Authority:|Traceable to:' src --include='*.spec.ts'",
	{ encoding: 'utf8' }
)
	.trim()
	.split('\n')
	.filter(Boolean);

const TAG = /#\{#[^}]*\}/g; // a single spec tag token, incl. `#{#rdc2b authority=developer}`

// Whole-line ceremony headers to drop entirely (JSDoc ` * ` prefix optional).
const DROP_LINE =
	/^\s*\*?\s*(Specifications covered|Authority|Priority|Traceable to|Specification|TDD Phase|TDD phase)\s*:/;
// Continuation lines of a dropped block that are pure tag-list items (no prose after the tag).
const PURE_TAG_ITEM = /^\s*\*?\s*-?\s*#\{#[^}]*\}\s*$/;

let changed = 0;
for (const file of list) {
	const src = readFileSync(file, 'utf8');
	const inLines = src.split('\n');
	const out = [];

	for (let raw of inLines) {
		// 1. Drop ceremonial header lines outright.
		if (DROP_LINE.test(raw)) continue;
		// 2. Drop bullet lines that were ONLY a tag (e.g. ` * - #{#spl1a}` with no prose).
		if (PURE_TAG_ITEM.test(raw)) continue;

		let line = raw;

		// 3. Remove tag tokens (+ one trailing space so `#{#x} Foo` -> `Foo`).
		line = line.replace(new RegExp(TAG.source + ' ?', 'g'), '');

		// 4. Clean up artifacts left by removal.
		// 4a. Degenerate parens that held only tags/separators: `()`, `(, )`, `(/)`, `(–d)`, `( , /)`.
		line = line.replace(/ *\([\s,/–-]*(?:[a-z][\s,/–-]*)*\)/g, '');
		// 4b. Collapse leftover separator runs like `, ,` or `,/` created by removed tags.
		line = line.replace(/([([])[\s,/–-]+/g, '$1'); // right after ( or [
		line = line.replace(/[\s,/]+([)\]])/g, '$1'); // right before ) or ]
		// 4c. Inside describe/it/test string labels, strip a leading/trailing `-`/`–` dangler.
		line = line.replace(
			/((?:describe|it|test)\(\s*['"`])\s*[-–]\s*/,
			'$1'
		);
		line = line.replace(/\s*[-–]\s*(['"`]\s*[,)])/, '$1');
		// 4d. Collapse doubled spaces (not leading indentation) and trim trailing ws.
		line = line.replace(/(\S) {2,}/g, '$1 ');
		line = line.replace(/[ \t]+$/g, '');

		out.push(line);
	}

	// 5. Collapse a JSDoc/comment block down to nothing-but-blank ` *` runs -> single blank.
	let text = out.join('\n');
	// Remove now-empty ` *` lines that are consecutive duplicates inside a block.
	text = text.replace(/(\n\s*\*)(\s*\n\s*\*\s*\n)/g, '$1\n');
	// Remove a comment block that became empty: `/**\n *\n */` or `/**\n */`.
	text = text.replace(/\/\*\*(?:\s*\n\s*\*)*\s*\n\s*\*\/\n/g, '');

	if (text !== src) {
		writeFileSync(file, text);
		changed++;
		console.log('updated', file);
	}
}
console.log(`\n${changed} files changed of ${list.length} scanned`);

