import { readFileSync, writeFileSync } from 'fs';
import { execSync } from 'child_process';

// `dry` mode writes transformed copies under .scratch/out/ instead of in place.
const dry = process.argv.includes('--dry');

const list = execSync(
	"grep -rlE '#\\{#|TDD Phase|should FAIL until|Specifications covered|Authority:|Traceable to:' src --include='*.spec.ts'",
	{ encoding: 'utf8' }
)
	.trim()
	.split('\n')
	.filter(Boolean);

// Whole ceremonial header lines to drop.
const DROP_LINE =
	/^\s*\*?\s*(Specifications covered|Authority|Priority|Traceable to|Specification|TDD Phase|TDD phase)\s*:/;
// A JSDoc/comment bullet that was ONLY a tag (no prose after it).
const PURE_TAG_ITEM = /^\s*\*?\s*-?\s*#\{#[^}]*\}\s*$/;
// A parenthetical composed solely of spec tags + separators (+ en-dash letter suffixes like `–d`).
// The leading lookahead REQUIRES a tag inside, so a code callback `()` is never matched.
const PAREN_TAGGROUP = / *\((?=[^)]*#\{#)(?:#\{#[^}]*\}|[\s,/]|[–-][a-z])*\)/g;
// A run of one or more tags joined by `/`, `,`, or spaces, plus a trailing ` - ` or single
// space, so `#{#a}/#{#b} - Foo`, `#{#a} #{#b} Foo`, and `#{#a} - Foo` all reduce to `Foo`.
const TAG_RUN = /#\{#[^}]*\}(?:\s*[/, ]\s*#\{#[^}]*\})*(?:\s*[-–]\s*| )?/g;

function transform(src) {
	const out = [];
	for (const raw of src.split('\n')) {
		if (DROP_LINE.test(raw)) continue;
		if (PURE_TAG_ITEM.test(raw)) continue;
		if (!raw.includes('#{#')) {
			out.push(raw); // no tag → leave code/prose exactly as-is
			continue;
		}
		let line = raw
			.replace(PAREN_TAGGROUP, '') // drop `(#{#a}, #{#b})` tag-group parentheticals
			.replace(TAG_RUN, '') // drop remaining inline tag runs (+ trailing ` - `)
			.replace(/\(\s+/g, '(') // `( URL Parameter Validation)` -> `(URL …)`
			// strip a dangling leading/trailing dash left in a describe/it/test label
			.replace(/((?:describe|it|test)\(\s*['"`])\s*[-–]\s*/, '$1')
			.replace(/\s*[-–]\s*(['"`]\s*[,)])/, '$1')
			.replace(/(\S) {2,}/g, '$1 ') // collapse doubled spaces (not indentation)
			.replace(/[ \t]+$/g, ''); // trim trailing whitespace
		out.push(line);
	}
	let text = out.join('\n');
	// Collapse consecutive empty ` *` comment lines to one; drop a fully-empty comment block.
	text = text.replace(/(\n\s*\*)(\s*\n\s*\*\s*\n)/g, '$1\n');
	text = text.replace(/\/\*\*(?:\s*\n\s*\*)*\s*\n\s*\*\/\n/g, '');
	return text;
}

let changed = 0;
for (const file of list) {
	const src = readFileSync(file, 'utf8');
	const text = transform(src);
	if (text === src) continue;
	changed++;
	if (dry) {
		const dest = '.scratch/out/' + file.replace(/\//g, '__');
		writeFileSync(dest, text);
	} else {
		writeFileSync(file, text);
	}
}
console.log(`${changed} files changed of ${list.length} scanned${dry ? ' (dry)' : ''}`);

