import { describe, it, expect } from 'vitest';
import { isPdfFile } from './pdfDetection';

/**
 * PDF Receipt Display Test Suite
 *
 * Validates PDF receipt detection and display behavior defined in:
 * specs/specifications/pdf-receipt-display.md
 *
 * TDD RED PHASE: These tests are written first and should FAIL until implementation is complete.
 */

describe('PDF Detection', () => {
	describe('isPdfFile utility', () => {
		it('should return true for .pdf extension', () => {
			expect(isPdfFile('receipts/user123/receipt.pdf')).toBe(true);
		});

		it('should return true for .PDF extension (case-insensitive)', () => {
			expect(isPdfFile('receipts/user123/RECEIPT.PDF')).toBe(true);
		});

		it('should return true for .Pdf extension (mixed case)', () => {
			expect(isPdfFile('receipts/user123/receipt.Pdf')).toBe(true);
		});

		it('should return false for .jpg extension', () => {
			expect(isPdfFile('receipts/user123/receipt.jpg')).toBe(false);
		});

		it('should return false for .png extension', () => {
			expect(isPdfFile('receipts/user123/receipt.png')).toBe(false);
		});

		it('should return false for .heic extension', () => {
			expect(isPdfFile('receipts/user123/receipt.heic')).toBe(false);
		});

		it('should return false for null/undefined path', () => {
			expect(isPdfFile(null)).toBe(false);
			expect(isPdfFile(undefined)).toBe(false);
		});

		it('should return false for empty string', () => {
			expect(isPdfFile('')).toBe(false);
		});

		it('should handle paths with multiple dots', () => {
			expect(isPdfFile('receipts/user.name/receipt.2024.pdf')).toBe(true);
		});

		it('should not match pdf in the middle of a filename', () => {
			expect(isPdfFile('receipts/pdf-receipt.jpg')).toBe(false);
		});
	});
});

