import { describe, it, expect } from 'vitest';
import {
	validatePassword,
	passwordsMatch,
	MIN_PASSWORD_LENGTH,
	MIN_LENGTH_MESSAGE,
	CHAR_TYPE_MESSAGE
} from './passwordValidation';

/**
 * Password Validation Test Suite
 *
 * This test suite validates password security requirements defined in:
 * specs/specifications/password-validation.md
 *
 * All tests are traceable to specific requirements using specification IDs
 */

describe('validatePassword', () => {
	describe('minimum length validation', () => {
		it('should reject passwords shorter than minimum length', () => {
			const result = validatePassword('Short1!');
			expect(result.isValid).toBe(false);
			expect(result.checks.minLength).toBe(false);
			expect(result.errors).toContain(MIN_LENGTH_MESSAGE);
		});

		it('should accept passwords exactly at minimum length with character type', () => {
			const result = validatePassword('A'.repeat(MIN_PASSWORD_LENGTH));
			expect(result.checks.minLength).toBe(true);
		});

		it('should accept passwords longer than minimum length with character type', () => {
			const result = validatePassword('A'.repeat(MIN_PASSWORD_LENGTH + 5));
			expect(result.checks.minLength).toBe(true);
		});

		it('should reject empty password', () => {
			const result = validatePassword('');
			expect(result.isValid).toBe(false);
			expect(result.checks.minLength).toBe(false);
		});
	});

	describe('character type validation', () => {
		it('should accept password with uppercase letter', () => {
			const result = validatePassword('A'.repeat(MIN_PASSWORD_LENGTH));
			expect(result.checks.hasCharacterType).toBe(true);
		});

		it('should accept password with lowercase letter', () => {
			const result = validatePassword('a'.repeat(MIN_PASSWORD_LENGTH));
			expect(result.checks.hasCharacterType).toBe(true);
		});

		it('should accept password with number', () => {
			const result = validatePassword('1'.repeat(MIN_PASSWORD_LENGTH));
			expect(result.checks.hasCharacterType).toBe(true);
		});

		it('should accept password with special character', () => {
			const result = validatePassword('!'.repeat(MIN_PASSWORD_LENGTH));
			expect(result.checks.hasCharacterType).toBe(true);
		});

		it('should accept password with multiple character types', () => {
			const result = validatePassword('Abc123!@#$%^&*()');
			expect(result.checks.hasCharacterType).toBe(true);
		});

		it('should reject password with no valid character types', () => {
			// This edge case is unlikely but tests the logic
			const result = validatePassword(' '.repeat(MIN_PASSWORD_LENGTH));
			expect(result.checks.hasCharacterType).toBe(false);
			expect(result.errors).toContain(CHAR_TYPE_MESSAGE);
		});
	});

	describe('overall validation', () => {
		it('should accept valid password with uppercase only', () => {
			const result = validatePassword('ABCDEFGHIJKLMNOP');
			expect(result.isValid).toBe(true);
			expect(result.errors).toHaveLength(0);
		});

		it('should accept valid password with lowercase only', () => {
			const result = validatePassword('abcdefghijklmnop');
			expect(result.isValid).toBe(true);
			expect(result.errors).toHaveLength(0);
		});

		it('should accept valid password with numbers only', () => {
			const result = validatePassword('1234567890123456');
			expect(result.isValid).toBe(true);
			expect(result.errors).toHaveLength(0);
		});

		it('should accept valid password with special chars only', () => {
			const result = validatePassword('!@#$%^&*()_+-=[]');
			expect(result.isValid).toBe(true);
			expect(result.errors).toHaveLength(0);
		});

		it('should accept valid password with mixed characters', () => {
			const result = validatePassword('MySecureP@ssw0rd!2025');
			expect(result.isValid).toBe(true);
			expect(result.errors).toHaveLength(0);
		});

		it('should reject password that is too short even with character types', () => {
			const result = validatePassword('Abc123!');
			expect(result.isValid).toBe(false);
			expect(result.errors).toContain(MIN_LENGTH_MESSAGE);
		});

		it('should reject password that is long enough but has no valid character types', () => {
			const result = validatePassword(' '.repeat(MIN_PASSWORD_LENGTH));
			expect(result.isValid).toBe(false);
			expect(result.errors).toContain(CHAR_TYPE_MESSAGE);
		});

		it('should reject password that fails both checks', () => {
			const result = validatePassword('   ');
			expect(result.isValid).toBe(false);
			expect(result.errors).toHaveLength(2);
			expect(result.errors).toContain(MIN_LENGTH_MESSAGE);
			expect(result.errors).toContain(CHAR_TYPE_MESSAGE);
		});
	});

	describe('special character support', () => {
		const specialChars = '!@#$%^&*()_+-=[]{}|;:,.<>?';

		specialChars.split('').forEach((char) => {
			it(`should accept special character: ${char}`, () => {
				const password = char.repeat(MIN_PASSWORD_LENGTH);
				const result = validatePassword(password);
				expect(result.checks.hasCharacterType).toBe(true);
			});
		});
	});

	describe('edge cases', () => {
		it('should handle unicode characters', () => {
			const result = validatePassword('émojis😀🎉🚀' + 'a'.repeat(10));
			expect(result.checks.minLength).toBe(true);
		});

		it('should handle very long passwords', () => {
			const result = validatePassword('a'.repeat(1000));
			expect(result.isValid).toBe(true);
		});
	});
});

describe('passwordsMatch', () => {
	it('should return true when passwords match and are non-empty', () => {
		expect(passwordsMatch('password123', 'password123')).toBe(true);
	});

	it('should return false when passwords do not match', () => {
		expect(passwordsMatch('password123', 'password456')).toBe(false);
	});

	it('should return false when both passwords are empty', () => {
		expect(passwordsMatch('', '')).toBe(false);
	});

	it('should return false when first password is empty', () => {
		expect(passwordsMatch('', 'password123')).toBe(false);
	});

	it('should return false when second password is empty', () => {
		expect(passwordsMatch('password123', '')).toBe(false);
	});

	it('should handle special characters in matching passwords', () => {
		expect(passwordsMatch('P@ssw0rd!#$', 'P@ssw0rd!#$')).toBe(true);
	});

	it('should be case-sensitive', () => {
		expect(passwordsMatch('Password123', 'password123')).toBe(false);
	});

	it('should handle whitespace correctly', () => {
		expect(passwordsMatch('pass word', 'pass word')).toBe(true);
		expect(passwordsMatch('password', 'pass word')).toBe(false);
	});
});

describe('exported constants', () => {
	it('should export MIN_PASSWORD_LENGTH as 16', () => {
		expect(MIN_PASSWORD_LENGTH).toBe(16);
	});

	it('should export MIN_LENGTH_MESSAGE with correct value', () => {
		expect(MIN_LENGTH_MESSAGE).toBe(`At least ${MIN_PASSWORD_LENGTH} characters`);
	});

	it('should export CHAR_TYPE_MESSAGE', () => {
		expect(CHAR_TYPE_MESSAGE).toBe(
			'At least one of: uppercase, lowercase, number, or special character'
		);
	});
});

